import javax.tools.*;import com.sun.source.util.JavacTask;import java.nio.file.*;import java.util.*;
public class ParseSources {public static void main(String[] args)throws Exception {var compiler=ToolProvider.getSystemJavaCompiler();var diagnostics=new DiagnosticCollector<JavaFileObject>();try(var manager=compiler.getStandardFileManager(diagnostics,null,null);var paths=Files.walk(Path.of("src"))){var files=paths.filter(p->p.toString().endsWith(".java")).map(Path::toFile).toList();var task=(JavacTask)compiler.getTask(null,manager,diagnostics,List.of("-proc:none"),null,manager.getJavaFileObjectsFromFiles(files));task.parse();long errors=diagnostics.getDiagnostics().stream().filter(d->d.getKind()==Diagnostic.Kind.ERROR).peek(System.err::println).count();System.out.println("Parsed "+files.size()+" Java source files; syntax errors: "+errors);if(errors>0)System.exit(1);}}}
